{
  "name": "data-agent-kit",
  "interface": {
    "displayName": "Data Agent Kit"
  },
  "plugins": [
    {
      "name": "alloydb",
      "source": {
        "source": "local",
        "path": "./alloydb"
      },
      "description": "Create, connect, and interact with an AlloyDB for PostgreSQL database and data.",
      "policy": {
        "installation": "AVAILABLE",
        "authentication": "ON_INSTALL"
      },
      "category": "Databases"
