      },
      "description": "Connect to Cloud SQL for SQL Server.",
      "policy": {
        "installation": "AVAILABLE",
        "authentication": "ON_INSTALL"
      },
      "category": "Databases"
    },
    {
      "name": "data-agent-kit-starter-pack",
      "source": {
        "source": "local",
        "path": "./data-agent-kit-starter-pack"
